import{d as u,C as t,o as c,c as g,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第五十六章","description":"从知者不言、和光同尘读玄同，辨明不受亲疏利害贵贱牵制的含义。","frontmatter":{"title":"道德经第五十六章","description":"从知者不言、和光同尘读玄同，辨明不受亲疏利害贵贱牵制的含义。","category":"guide","aliases":["道德经第五十六章","老子第五十六章","dao de jing chapter 56"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-56.md","filePath":"daoism/dao-de-jing/chapter-56.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-56.md"},_=u({...b,setup(p){const r=[{id:"knowing-and-not-stirring",label:"知者不言",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"者不言，言者不",{text:"知",glossary:"zhi"},"。"]],note:["【白话】真正有所知的人，不以言语妄造事端；一味以言语制造事端的人，并未把握道。这是本章沿自然与守质展开的对举。","【王弼注择要】知者不言下注「因自然也」，言者不知下注「造事端也」。注以是否因循自然来分辨这两种言知关系。","【读法】知读 zhī，取认识、了解义。不言与第二章不言之教相参，不能仅凭一个人话少就断定他知，也不能由此免除必要的说明与沟通。"]},{id:"closing-and-untying",label:"挫其锐，解其纷",showLabel:!0,sentences:[[{text:"塞",glossary:"se"},"其",{text:"兑",glossary:"dui"},"，闭其门，",{text:"挫",glossary:"cuo"},"其锐，",{text:"解",glossary:"jie"},"其",{text:"纷",glossary:"fen"},"，"]],note:["【白话】收住欲念纷出的孔窍，关上它的门户，收敛锋芒，解开纷乱。前两句写守住，后两句写消减争胜与纠结。","【王弼注择要】塞兑闭门挫锐下注「含守质也」；所据经文解其分下注「除争原也」，把解纷理解为消除争端的根源。","【读法】兑与门可连第五十二章事欲生发的门户读；所据录文这里作分，本站保留纷。挫锐不必解释成压制一切能力，解纷也不等于掩盖实际冲突。"]},{id:"light-and-dust",label:"是谓玄同",showLabel:!0,sentences:[[{text:"和其光",glossary:"heguang"},"，",{text:"同其尘",glossary:"tongchen"},"，是谓",{text:"玄同",glossary:"xuantong"},"。"]],note:["【白话】调和自己的光彩，与尘世相处，不以自显和鄙弃划出偏执的界限；这种深层的会通，叫作玄同。","【王弼注择要】和光下注「无所特显，则物无偏争也」，同尘下注「无所特贱，则物无偏耻也」。两句分别从不特显、不特贱解释少争与少耻。","【读法】和其光在此取调和、收敛显耀之意，与第五十五章和之至的生命和合义分开。玄同仍容许辨别是非与处理差异，不是要求参与不当之事。"]},{id:"beyond-opposed-hold",label:"不可得而亲，不可得而疏",showLabel:!0,sentences:[["故不可得而",{text:"亲",glossary:"qin"},"，不可得而",{text:"疏",glossary:"shu"},"；不可得而",{text:"利",glossary:"li"},"，不可得而",{text:"害",glossary:"hai"},"；不可得而",{text:"贵",glossary:"gui"},"，不可得而",{text:"贱",glossary:"jian"},"。"]],note:["【白话】所以，不能用亲近笼络他，也不能用疏远排拒他；不能用利益诱取他，也不能用损害胁迫他；不能以抬高地位使他自满，也不能以贬低地位使他自失。","【王弼注择要】「可得而亲，则可得而疏也。」另两组注同样说「可得而利，则可得而害也」「可得而贵，则可得而贱也」，揭出一旦受一端支配，便会受其相对一端支配。","【读法】上述笼络、胁迫是本站为说明关系牵制所作的白话展开。不可得不承诺现实中免受损失，也不取消人与人的亲爱、互助和必要界限。"]},{id:"valued-by-the-world",label:"故为天下贵",showLabel:!0,sentences:[["故为天下",{text:"贵",glossary:"guivalued"},"。"]],note:["【白话】因此，这样的人反而为天下所尊重。他的可贵，不依赖某一方给予的亲近、好处或位次。","【王弼注择要】「无物可以加之也。」注承上句，写外物难以加其牵制，不以可贵交换他人的操纵。","【读法】为天下贵取被天下看重，与前段使之显贵、使之卑贱的处置分开；本章指出一种立身尺度，不保证所有人的认可。"]}],o=[{id:"zhi",term:"知",sense:2,pinyin:"zhī"},{id:"se",term:"塞",sense:1},{id:"dui",term:"兑",sense:1},{id:"cuo",term:"挫",sense:1},{id:"jie",term:"解",sense:1},{id:"fen",term:"纷",sense:1},{id:"heguang",term:"和其光",sense:1},{id:"tongchen",term:"同其尘",sense:1},{id:"xuantong",term:"玄同",sense:1},{id:"qin",term:"亲",sense:1},{id:"shu",term:"疏",sense:1},{id:"li",term:"利",sense:2},{id:"hai",term:"害",sense:1},{id:"gui",term:"贵",sense:2},{id:"jian",term:"贱",sense:2},{id:"guivalued",term:"贵",sense:3}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十六章",tabindex:"-1"},[s("道德经第五十六章 "),a("a",{class:"header-anchor",href:"#道德经第五十六章","aria-label":'Permalink to "道德经第五十六章"'},"​")],-1)),n(i,{title:"玄同如何超出亲疏、利害与贵贱的牵制",summary:"本章先以不言与守质消解造作，再由挫锐、解纷、和光、同尘写出玄同，最后落在不受亲疏、利害、贵贱左右。王弼沿因自然、除争原解释，所说不言并不等于以沉默拒绝一切表达。",points:[{label:"先读",text:"把不言放在因自然、不造事端的脉络中，与第二章不言之教相参。"},{label:"再辨",text:"挫锐解纷与和光同尘接续第四章；王注把重点落在消除争端、不特别自显或贱物。"},{label:"后看",text:"三组不可得写不受相对关系挟制，末句的贵与被抬高、被贬低的地位分开。"}],hint:"塞读 sè，兑读 duì，挫读 cuò；知者的知读 zhī，解其纷的解读 jiě。本站纷字与录文分字分别注明。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"知者不言，言者不知。",tone:"从自然辨言知",guide:"依王注看是否妄造事端，不按说话多少衡量一切认识。"},{text:"和其光，同其尘，是谓玄同。",tone:"不特显，也不特贱",guide:"与第四章相参，留意两种分别心如何引出偏争、偏耻。"},{text:"故为天下贵。",tone:"可贵不靠外在抬高",guide:"承接三组不可得，区分受人摆布的位次与不受牵制的可贵。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-六个动作怎样通到玄同" tabindex="-1">象：六个动作怎样通到玄同？ <a class="header-anchor" href="#象-六个动作怎样通到玄同" aria-label="Permalink to &quot;象：六个动作怎样通到玄同？&quot;">​</a></h3><p>塞兑闭门先收住欲念的出入，挫锐解纷再消减争胜，和光同尘则松开特别自显和贱弃他物的区分。它们共同指向不以偏私制造对立，而不是把一切差异强行变成一样。</p><h3 id="理-为什么亲与疏、利与害、贵与贱成对出现" tabindex="-1">理：为什么亲与疏、利与害、贵与贱成对出现？ <a class="header-anchor" href="#理-为什么亲与疏、利与害、贵与贱成对出现" aria-label="Permalink to &quot;理：为什么亲与疏、利与害、贵与贱成对出现？&quot;">​</a></h3><p>王弼逐组指出，可被一端取得的人，也会落入另一端的影响。若地位、利益或亲疏成为唯一立身凭借，失去它们就容易自失；玄同因此要松开这种依赖。</p><h3 id="用-怎样把不受牵制落实到相处中" tabindex="-1">用：怎样把不受牵制落实到相处中？ <a class="header-anchor" href="#用-怎样把不受牵制落实到相处中" aria-label="Permalink to &quot;用：怎样把不受牵制落实到相处中？&quot;">​</a></h3><p>在接受赞许、利益或关系邀请前，先辨明自己能否提出异议、说明限度。可以保持亲近并接受帮助，同时保有判断与退出不当安排的能力。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>少以显耀和鄙弃组织关系。</strong> 让能力服务实际事务，也给他人留下体面。判断行为时说明事实和影响，避免把人固定成值得追捧或可以轻贱的两类。</p><p><strong>把可贵放在可持守的尺度上。</strong> 当评价和位次变化时，仍有可以说明的做事原则。这样更容易接纳善意，也更能辨认附带不合理条件的好处。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否把某人的亲近、赞许或给予当成唯一凭借？如果这些评价改变，我还能够持守什么，又该在哪里说明自己的界限？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 015b–016a 电子录文核对；本站解其纷，录文作解其分。</li><li>录文兊、鋭、塵、䟽等，本站用兑、锐、尘、疏；字形转换与纷／分的字面差异分别处理，未逐字核对影印。</li><li>古注择要以因自然、守质、除争原贯通玄同；亲疏利害贵贱的白话关系说明属于本站解释，不额外补作古注。</li><li>知用认识义并标 zhī；利、贵、贱依本句动词及末句被看重之义分列，不用旧页的材料利益、贵贱本末义硬套。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，015b–016a</a>。</p>',15))])}}});export{f as __pageData,_ as default};
